#if HAVE_BROKER_TLS
namespace
{
	bool live_exchange(const char* host, const char* port, const std::string& pin, bool read_challenge)
	{
		WSADATA wsa{};
		if (WSAStartup(MAKEWORD(2, 2), &wsa) != 0) return false;
		addrinfo hints{}, *found = nullptr;
		hints.ai_family = AF_INET;
		hints.ai_socktype = SOCK_STREAM;
		SOCKET peer = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
		bool ok = peer != INVALID_SOCKET && getaddrinfo(host, port, &hints, &found) == 0 && found && connect(peer, found->ai_addr, int(found->ai_addrlen)) == 0;
		if (ok)
		{
			broker_tls::client tls;
			std::string error;
			ok = tls.handshake(peer, host, pin, error);
			if (ok && read_challenge)
			{
				fd_set readable;
				FD_ZERO(&readable);
				FD_SET(peer, &readable);
				timeval timeout{5, 0};
				char chunk[4096];
				const int n = select(0, &readable, nullptr, nullptr, &timeout) > 0 ? recv(peer, chunk, sizeof(chunk), 0) : 0;
				std::string plain;
				ok = n > 0 && tls.decrypt(reinterpret_cast<const std::uint8_t*>(chunk), std::size_t(n), plain, error) &&
				     plain.find("\"op\":\"challenge\"") != std::string::npos && plain.find("\"v\":2") != std::string::npos;
			}
		}
		if (found) freeaddrinfo(found);
		if (peer != INVALID_SOCKET) closesocket(peer);
		WSACleanup();
		return ok;
	}
}
#endif

int main(int argc, char** argv)
{
#if HAVE_BROKER_TLS
	if (argc == 5 && std::string(argv[1]) == "--live")
	{
		check(live_exchange(argv[2], argv[3], argv[4], true), "live broker TLS: the pinned protocol-2 challenge arrives");
		check(!live_exchange(argv[2], argv[3], std::string(64, '0'), false), "live broker TLS: a wrong pin fails before the challenge");
		std::printf("%d PASS / %d FAIL\n", passes, failures);
		return failures ? 1 : 0;
	}
	const std::string expected = "5accba244809bb6c9a2c2f5bdb4e5d30fb5ec737d59bf87a8fc9031d81cf8a5a";
	std::array<std::uint8_t, broker_tls::pin_size> pin{};
	check(broker_tls::parse_pin(expected, pin) && !broker_tls::parse_pin(expected.substr(1), pin) && !broker_tls::parse_pin(std::string(64, 'z'), pin),
	      "broker pin: exactly 64 hexadecimal characters are required");
	PCCERT_CONTEXT certificate = CertCreateCertificateContext(X509_ASN_ENCODING | PKCS_7_ASN_ENCODING, certificate_der, sizeof(certificate_der));
	check(certificate != nullptr, "broker certificate: owned DER fixture loads");
	if (certificate)
	{
		std::array<std::uint8_t, broker_tls::pin_size> actual{};
		check(broker_tls::certificate_spki_sha256(certificate, actual) && actual == pin,
		      "broker certificate: SHA-256 covers the exact SubjectPublicKeyInfo DER, matching OpenSSL");
		std::string error;
		check(broker_tls::verify_certificate(certificate, L"broker.test", expected, error),
		      "broker certificate: the matching SPKI pin authenticates a self-signed leaf");
		check(!broker_tls::verify_certificate(certificate, L"broker.test", std::string(64, '0'), error),
		      "broker certificate: a wrong SPKI pin fails closed");
		check(!broker_tls::verify_certificate(certificate, L"broker.test", "", error),
		      "broker certificate: an untrusted self-signed leaf cannot use the public-CA path");
		CertFreeCertificateContext(certificate);
	}
	const auto protocols = broker_tls::enabled_protocols();
	check((protocols & SP_PROT_TLS1_2_CLIENT) != 0 && (protocols & (SP_PROT_TLS1_CLIENT | SP_PROT_TLS1_1_CLIENT)) == 0,
	      "broker TLS: TLS 1.0/1.1 are disabled and TLS 1.2 is enabled");
#else
	check(false, "broker pin: exactly 64 hexadecimal characters are required");
	check(false, "broker certificate: exact SubjectPublicKeyInfo SHA-256");
	check(false, "broker certificate: matching and wrong pin behavior");
	check(false, "broker TLS: TLS 1.2+ only");
#endif
	std::printf("%d PASS / %d FAIL\n", passes, failures);
	return failures ? 1 : 0;
}
